export type ThemeName = 'light' | 'dark';

export interface ThemeColors {
  background: string;
  surface: string;
  surfaceElevated: string;
  border: string;
  borderStrong: string;

  text: string;
  textSecondary: string;
  textMuted: string;
  textOnPrimary: string;

  primary: string;
  primaryHover: string;
  primarySoft: string;
  primaryText: string;

  live: string;
  liveSoft: string;
  liveText: string;

  danger: string;
  dangerSoft: string;
  warning: string;

  /** Partial (non-final) transcript text — lower contrast, still AA-legible. */
  transcriptPartial: string;
  transcriptFinal: string;

  /** Focus ring for keyboard navigation (WCAG 2.2 §2.4.11/2.4.13). */
  focusRing: string;
  overlay: string;
}

