// ---------------------------------------------------------------------------
// Web bridge
// ---------------------------------------------------------------------------

function toKebab(key: string): string {
  return key.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
}

/** Emits the `--ll-*` custom properties consumed by the web stylesheet. */
export function cssVariables(theme: ThemeName): Record<string, string> {
  const colors = themes[theme];
  const vars: Record<string, string> = {};
  for (const [key, value] of Object.entries(colors)) {
    vars[`--ll-color-${toKebab(key)}`] = value;
  }
  for (const [key, value] of Object.entries(radius)) {
    vars[`--ll-radius-${toKebab(key)}`] = `${value}px`;
  }
  for (const [key, value] of Object.entries(spacing)) {
    vars[`--ll-space-${toKebab(key)}`] = `${value}px`;
  }
  for (const [key, value] of Object.entries(fontSize)) {
    vars[`--ll-font-size-${toKebab(key)}`] = `${value}px`;
  }
  for (const [key, value] of Object.entries(duration)) {
    vars[`--ll-duration-${toKebab(key)}`] = `${value}ms`;
  }
  vars['--ll-font-family'] = fontFamily.web;
  vars['--ll-font-family-mono'] = fontFamily.webMono;
  for (const [key, value] of Object.entries(blue)) {
    vars[`--ll-blue-${key}`] = value;
  }
  for (const [name, color] of Object.entries(conversation)) {
    vars[`--ll-talk-${name}`] = color.base;
    vars[`--ll-talk-${name}-soft`] = theme === 'dark' ? color.softDark : color.soft;
    vars[`--ll-talk-${name}-text`] = theme === 'dark' ? color.textDark : color.text;
  }
  for (const [key, value] of Object.entries(breakpoint)) {
    vars[`--ll-breakpoint-${key}`] = `${value}px`;
  }
  for (const [key, value] of Object.entries(tracking)) {
    vars[`--ll-tracking-${toKebab(key)}`] = value;
  }
  vars['--ll-easing-standard'] = easing.standard;
  vars['--ll-easing-spring'] = easing.spring;
  vars['--ll-easing-decelerate'] = easing.decelerate;
  vars['--ll-shadow-card'] = shadow.card.web;
  vars['--ll-shadow-raised'] = shadow.raised.web;
  vars['--ll-shadow-pressed'] = shadow.pressed.web;
  vars['--ll-shadow-speaking'] = shadow.speaking.web;
  vars['--ll-material-bar'] = material.bar[theme];
  vars['--ll-material-bar-blur'] = material.bar.blur;
  vars['--ll-material-sheet'] = material.sheet[theme];
  vars['--ll-material-sheet-blur'] = material.sheet.blur;
  vars['--ll-min-touch-target'] = `${MIN_TOUCH_TARGET}px`;
  return vars;
}

export function cssVariableBlock(theme: ThemeName, selector: string): string {
  const entries = Object.entries(cssVariables(theme))
    .map(([key, value]) => `  ${key}: ${value};`)
    .join('\n');
  return `${selector} {\n${entries}\n}`;
}

// ---------------------------------------------------------------------------
// Contrast — asserted by unit tests so a palette edit cannot silently regress
// accessibility.
// ---------------------------------------------------------------------------

function channelLuminance(channel: number): number {
  const c = channel / 255;
  return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

export function hexToRgb(hex: string): { r: number; g: number; b: number } | null {
  const normalized = hex.replace('#', '').trim();
  if (normalized.length !== 6) return null;
  const r = Number.parseInt(normalized.slice(0, 2), 16);
  const g = Number.parseInt(normalized.slice(2, 4), 16);
  const b = Number.parseInt(normalized.slice(4, 6), 16);
  if ([r, g, b].some((v) => Number.isNaN(v))) return null;
  return { r, g, b };
}

export function relativeLuminance(hex: string): number {
  const rgb = hexToRgb(hex);
  if (!rgb) return 0;
  return (
    0.2126 * channelLuminance(rgb.r) +
    0.7152 * channelLuminance(rgb.g) +
    0.0722 * channelLuminance(rgb.b)
  );
}

/** WCAG 2.x contrast ratio, 1–21. */
export function contrastRatio(foreground: string, background: string): number {
  const l1 = relativeLuminance(foreground);
  const l2 = relativeLuminance(background);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

export function meetsContrastAA(
  foreground: string,
  background: string,
  size: 'normal' | 'large' = 'normal',
): boolean {
  return contrastRatio(foreground, background) >= (size === 'large' ? 3 : 4.5);
}
